        sb.AppendLine("// §L2 — EffectAlgebraGenerator 骨架生成的校验注册桩（非运行期代码，仅为标注索引）。");
        sb.AppendLine("// 数学在 L1（Cosmos.EffectAlgebra）；本桩仅标记「被标注方法」并预留 Union 注入点。");
        sb.AppendLine("// L2 残差（honest）：§7 白名单是 Godot 运行时 API 数据，编译期不可用；");
        sb.AppendLine("// 真实 Claim 注入待 L2 运行期解析（见 LANDING_PLAN §4），此处不重算代数（避免假绿）。");
        sb.AppendLine("namespace Cosmos.EffectAlgebra.Generated;");
        sb.AppendLine();
        sb.AppendLine("public static partial class EffectAlgebraGenerated");
        sb.AppendLine("{");
        sb.AppendLine($"    /// <summary>§L2 桩：方法 {m.MethodName} 标注了 {tags}——类型边界由 L1 强制，此处仅预留 baseSig + 对应 ApiMapping.Claims 的 Union 注入点。</summary>");
        sb.AppendLine($"    public static Cosmos.EffectAlgebra.Signature Compute{m.MethodName}(Cosmos.EffectAlgebra.Signature baseSig)");
        sb.AppendLine("    {");
        sb.AppendLine("        // L2 残差（honest）：编译期无法取得该方法对应 GodotApiWhitelist 的实例 Claims，");
        sb.AppendLine("        // 故返回 baseSig 透传；运行期注入见 LANDING_PLAN §4。代数计算仍由 L1 完成（§3.1–§3.3）。");
        sb.AppendLine("        return baseSig;");
        sb.AppendLine("    }");
        sb.AppendLine("}");
        return sb.ToString();
    }

    private sealed record AnnotatedMethod(string MethodName, bool HasOverride, bool HasAccept);
}

